export type FixtureKey = keyof typeof FIXTURES

/** The order multi-file stories open them in. */
export const OPEN_ORDER: FixtureKey[] = ['pdf', 'xlsx', 'png', 'json', 'md', 'ts', 'docx', 'csv']

/** Fetch bytes for a fixture (renderers do this themselves; exported for sharing). */
export async function loadBytes(file: ViewerFile, signal?: AbortSignal): Promise<ArrayBuffer> {
	const response = await fetch(file.url, { signal })
	if (!response.ok) throw new Error(`${file.name}: ${response.status}`)
	return response.arrayBuffer()
}

export async function loadText(file: ViewerFile, signal?: AbortSignal): Promise<string> {
	return new TextDecoder('utf-8').decode(await loadBytes(file, signal))
}
